const startPairPrompt = `-- name: StartPairPrompt :one
UPDATE pair_prompt_queue
SET status = 'running',
    run_id = $1::text,
    started_at = NOW()
WHERE id = $2
  AND session_id = $3::text
  AND status = 'claimed'
  AND executor_client_id = $4::text
RETURNING id, session_id, seq, author_user_id, source, body, status, executor_client_id, claim_expires_at, run_id, canceled_by, created_at, started_at, finished_at
`

type StartPairPromptParams struct {
	RunID            string `json:"run_id"`
	ID               string `json:"id"`
	SessionID        string `json:"session_id"`
	ExecutorClientID string `json:"executor_client_id"`
}

// Start CAS: write run_id + flip to running BEFORE streaming. Failure = abort
// without dispatch (the claim was cancelled/taken over). session_id is part of
// the CAS so a role check against one session can never mutate another's row.
func (q *Queries) StartPairPrompt(ctx context.Context, arg StartPairPromptParams) (PairPromptQueue, error) {
	row := q.db.QueryRow(ctx, startPairPrompt,
		arg.RunID,
		arg.ID,
		arg.SessionID,
		arg.ExecutorClientID,
	)
	var i PairPromptQueue
	err := row.Scan(
		&i.ID,
		&i.SessionID,
		&i.Seq,
		&i.AuthorUserID,
		&i.Source,
		&i.Body,
		&i.Status,
		&i.ExecutorClientID,
		&i.ClaimExpiresAt,
		&i.RunID,
		&i.CanceledBy,
		&i.CreatedAt,
		&i.StartedAt,
		&i.FinishedAt,
	)
	return i, err
}

const sweepStalePairPromptClaims = `-- name: SweepStalePairPromptClaims :many
UPDATE pair_prompt_queue
SET status = 'queued',
    executor_client_id = NULL,
    claim_expires_at = NULL
WHERE status = 'claimed'
  AND run_id IS NULL
  AND claim_expires_at < NOW()
RETURNING id, session_id, seq, author_user_id, source, body, status, executor_client_id, claim_expires_at, run_id, canceled_by, created_at, started_at, finished_at
`

// Server sweep: revert expired 'claimed' rows WITHOUT a run_id back to 'queued'.
// Rows WITH a run_id are never reverted — run_id is the never-re-dispatch marker.
func (q *Queries) SweepStalePairPromptClaims(ctx context.Context) ([]PairPromptQueue, error) {
	rows, err := q.db.Query(ctx, sweepStalePairPromptClaims)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PairPromptQueue{}
	for rows.Next() {
		var i PairPromptQueue
		if err := rows.Scan(
			&i.ID,
			&i.SessionID,
			&i.Seq,
			&i.AuthorUserID,
			&i.Source,
			&i.Body,
			&i.Status,
			&i.ExecutorClientID,
			&i.ClaimExpiresAt,
			&i.RunID,
			&i.CanceledBy,
			&i.CreatedAt,
			&i.StartedAt,
			&i.FinishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

