const updatePairSessionMemberPresence = `-- name: UpdatePairSessionMemberPresence :one
UPDATE pair_session_members
SET presence = $3,
    presence_updated_at = NOW(),
    last_seen_at = NOW()
WHERE session_id = $1
  AND user_id = $2
  AND removed_at IS NULL
  AND EXISTS (
    SELECT 1 FROM pair_sessions
    WHERE pair_sessions.id = pair_session_members.session_id
      AND pair_sessions.status NOT IN ('ended', 'failed')
  )
RETURNING session_id, user_id, role, invited_via_invite_id, presence, presence_updated_at, last_seen_at, joined_at, removed_at
`

type UpdatePairSessionMemberPresenceParams struct {
	SessionID string          `json:"session_id"`
	UserID    int64           `json:"user_id"`
	Presence  json.RawMessage `json:"presence"`
}

// 80ms cursor/caret beat writes ONLY this member's row, and only while the
// member and the session are both live, so a beat racing a removal or an end
// cannot write after it.
func (q *Queries) UpdatePairSessionMemberPresence(ctx context.Context, arg UpdatePairSessionMemberPresenceParams) (PairSessionMember, error) {
	row := q.db.QueryRow(ctx, updatePairSessionMemberPresence, arg.SessionID, arg.UserID, arg.Presence)
	var i PairSessionMember
	err := row.Scan(
		&i.SessionID,
		&i.UserID,
		&i.Role,
		&i.InvitedViaInviteID,
		&i.Presence,
		&i.PresenceUpdatedAt,
		&i.LastSeenAt,
		&i.JoinedAt,
		&i.RemovedAt,
	)
	return i, err
}

const upsertPairSessionDraft = `-- name: UpsertPairSessionDraft :one

INSERT INTO pair_session_draft (session_id, content, version, updated_by, updated_at)
VALUES ($1::text, $2, $3, $4, NOW())
ON CONFLICT (session_id) DO UPDATE
SET content = EXCLUDED.content,
    version = EXCLUDED.version,
    updated_by = EXCLUDED.updated_by,
    updated_at = NOW()
WHERE EXCLUDED.version > pair_session_draft.version
RETURNING session_id, content, version, updated_by, updated_at
`

type UpsertPairSessionDraftParams struct {
	SessionID string      `json:"session_id"`
	Content   string      `json:"content"`
	Version   int64       `json:"version"`
	UpdatedBy pgtype.Int8 `json:"updated_by"`
}

// ---- Pair session draft (co-compose) ----
// Version-gated apply: only advance when the incoming version strictly exceeds
// the stored version (stale writes are rejected by leaving the row unchanged
// and returning nothing via the WHERE guard on conflict).
func (q *Queries) UpsertPairSessionDraft(ctx context.Context, arg UpsertPairSessionDraftParams) (PairSessionDraft, error) {
	row := q.db.QueryRow(ctx, upsertPairSessionDraft,
		arg.SessionID,
		arg.Content,
		arg.Version,
		arg.UpdatedBy,
	)
	var i PairSessionDraft
	err := row.Scan(
		&i.SessionID,
		&i.Content,
		&i.Version,
		&i.UpdatedBy,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertPairSessionMember = `-- name: UpsertPairSessionMember :one

INSERT INTO pair_session_members (
    session_id,
    user_id,
    role,
    invited_via_invite_id
)
VALUES (
    $1::text,
    $2,
    $3::text,
    $4
)
ON CONFLICT (session_id, user_id) DO UPDATE
SET role = EXCLUDED.role,
    invited_via_invite_id = COALESCE(EXCLUDED.invited_via_invite_id, pair_session_members.invited_via_invite_id)
WHERE pair_session_members.removed_at IS NULL
RETURNING session_id, user_id, role, invited_via_invite_id, presence, presence_updated_at, last_seen_at, joined_at, removed_at
`

type UpsertPairSessionMemberParams struct {
	SessionID          string      `json:"session_id"`
	UserID             int64       `json:"user_id"`
	Role               string      `json:"role"`
	InvitedViaInviteID pgtype.UUID `json:"invited_via_invite_id"`
}

// ---- Pair session members ----
// Never resurrect a removed (revoked) member: a still-live link must not let a
// revoked user readmit themselves (returns no row instead). Readmission goes
// through an owner-granted invite (AcceptPairSessionInvite clears removed_at).
func (q *Queries) UpsertPairSessionMember(ctx context.Context, arg UpsertPairSessionMemberParams) (PairSessionMember, error) {
	row := q.db.QueryRow(ctx, upsertPairSessionMember,
		arg.SessionID,
		arg.UserID,
		arg.Role,
		arg.InvitedViaInviteID,
	)
	var i PairSessionMember
	err := row.Scan(
		&i.SessionID,
		&i.UserID,
		&i.Role,
		&i.InvitedViaInviteID,
		&i.Presence,
		&i.PresenceUpdatedAt,
		&i.LastSeenAt,
		&i.JoinedAt,
		&i.RemovedAt,
	)
	return i, err
}
